import { authGuard } from './core/auth.guard';
import { LoginComponent } from './auth/login/login.component';
import { DashboardComponent } from './dashboard/dashboard.component';
import { ProduitFormComponent } from './produits/produit-form/produit-form.component';
import { ProduitListComponent } from './produits/produit-list/produit-list.component';
export const routes = [{
  path: 'login',
  component: LoginComponent
}, {
  path: 'dashboard',
  component: DashboardComponent,
  canActivate: [authGuard]
}, {
  path: 'produits',
  component: ProduitListComponent,
  canActivate: [authGuard]
}, {
  path: 'produits/nouveau',
  component: ProduitFormComponent,
  canActivate: [authGuard]
}, {
  path: 'produits/:id/modifier',
  component: ProduitFormComponent,
  canActivate: [authGuard]
}, {
  path: '',
  redirectTo: 'dashboard',
  pathMatch: 'full'
}];
